L000211	\section{Derivation of the effective Lindblad operator for the common reservoir}
L000212	
L000213	Two bosonic modes coupled to a common reservoir exhibit the collective dissipative channel governed by the effective Lindblad operator $L_c=\sqrt{\Gamma}(p_aa+p_bb)$. We show that this mechanism can be implemented either via an auxiliary cavity mode that is adiabatically eliminated, or via directly coupling to a common one-dimensional waveguide.
L000214	\subsection{Constructing $L_c$ via the auxiliary cavity mode}
L000215	We first consider two cavity modes $a$ and $b$ with the same frequency, interacting through a strongly damped auxiliary cavity mode $z$. In this configuration, the auxiliary mode decays rapidly and continually extracts information from the cavity modes $a$ and $b$. Adiabatic elimination of this fast mode generates an effective Lindblad operator $L_c$. The detailed derivation is as follows. The Hamiltonian of the total system is
L000216	\begin{align}
L000217		H^{\rm tot}=H+H^z+H^{\mathrm{int}},
L000218	\end{align}
L000219	with $H^z=\delta z^{\dag}z$, $H^{\mathrm{int}}=(g_aa+g_bb)z^{\dag}+\mathrm{H.c.}=Qz^{\dag}+\mathrm{H.c.}$, where $\delta$ denotes the detuning between the cavity mode and the reservoir. The dynamics obeys the master equation
L000220	\begin{align}
L000221		\dot{\rho}_{\rm tot}=-i[H^{\rm tot},\rho_{\rm tot}]+\kappa_z\mathcal{L}[z]\rho_{\rm tot}=\mathcal{L}\rho_{\rm tot}+\mathcal{L}_z\rho_{\rm tot}+\mathcal{V}\rho_{\rm tot},
L000222	\end{align}
L000223	where $\mathcal{L}\bullet=-i[H,\bullet]$, $\mathcal{L}_z\bullet=-i[H^z,\bullet]+\kappa_z\mathcal{L}[z]\bullet$, and $\mathcal{V}\bullet=-i[H^{\mathrm{int}},\bullet]$, with $\mathcal{L}[o]\rho=o\rho o^{\dag}-1/2\{o^{\dag}o,\rho\}$. Because the auxiliary mode is strongly dissipative, $\kappa_z\gg\{g_a, g_b, \delta, ||H||\}$, the evolution of the subsystem governed by $H$ is relatively slow, whereas the sector described by $H^z$ relaxes rapidly. The auxiliary cavity relaxes to its unique steady state $\rho_z^{\rm ss}=|0\rangle_z\langle0|$, which satisfies $\mathcal{L}_z\rho_z^{\rm ss}=0$. To eliminate the fast subsystem, we employ the standard adiabatic–elimination expansion $\dot{\rho}=\sum_{i\geq0}L_i\rho$, where $\rho=\mathrm{Tr}_z(\rho_{\rm tot})$ represents the density operator of the system composed of cavity modes $a$ and $b$~\cite{Azouit_2017,7798963,PhysRevA.102.032212}. The zeroth-order contribution vanishes because the fast sector remains in $\rho_z^{\rm ss}$, with $L_0\rho=0$~\cite{PhysRevA.109.032603}. Under the first-order approximation, we obtain~\cite{Azouit_2017}
L000224	\begin{align}
L000225		L_1\rho=\mathcal{L}\rho+\mathrm{Tr}_z(\mathcal{V}\rho_{\rm tot})=\mathcal{L}\rho-i\mathrm{Tr}_z([H^{\mathrm{int}},\rho \otimes\rho_z^{\rm ss}])=\mathcal{L}\rho.
L000226	\end{align}
L000227	
L000228	Furthermore, the dynamics of the slow subsystem can be represented by a linear, time-invariant Kraus map $\mathcal{K}$, such that the full density matrix satisfies $\rho_{\rm tot}=\mathcal{K}(\rho)$. Within the adiabatic-elimination expansion, the second-order contribution to the effective generator is given by~\cite{Azouit_2017}
L000229	\begin{align}
L000230		L_2\rho=\mathrm{Tr}_z(\mathcal{V}(\mathcal{K}_1(\rho))),
L000231	\end{align}
L000232	with $\mathcal{K}_1(\rho)=\overline{\tau}\overline{\mathcal{K}}_z(\mathcal{V}(\rho\otimes\rho_z^{\rm ss}))+\mathbf{G}_{1,s}(\rho)$. Here $\mathbf{G}_{1,s}$ is the gauge choice associated with the completely-positive, trace-preserving representation for the reduced slow dynamics, where we select $\mathbf{G}_{1,s}(\rho)=-\overline{\tau}\mathrm{Tr}_z(\mathcal{V}(\rho\otimes\rho_z^{\rm ss}))$ for simplicity~\cite{Azouit_2017,PhysRevA.109.062206}. With this choice, we have
L000233	\begin{align}
L000234		\mathcal{K}_1(\rho)&=\overline{\tau}\overline{\mathcal{K}}_z(\mathcal{V}(\rho\otimes\rho_z^{\rm ss}))-\overline{\tau}\mathrm{Tr}_z(\mathcal{V}(\rho\otimes\rho_z^{\rm ss}))\notag\\
L000235		&=-i\overline{\tau}\overline{\mathcal{K}}_z(Q\rho\otimes|1\rangle_z\langle0|-\rho Q^{\dag}\otimes|0\rangle_z\langle1|)+i\overline{\tau}\mathrm{Tr}_z(Q\rho\otimes|1\rangle_z\langle0|-\rho Q^{\dag}\otimes|0\rangle_z\langle1|)\notag\\
L000236		&=-i\Big(\frac{Q\rho}{i\delta+\kappa_z/2}\otimes|1\rangle_z\langle0|-\frac{\rho Q^{\dag}}{-i\delta+\kappa_z/2}\otimes|0\rangle_z\langle1|\Big).
L000237	\end{align}
L000238	Then, the second–order contribution
L000239	\begin{align}
L000240		L_2\rho&=\mathrm{Tr}_z(\mathcal{V}(\mathcal{K}_1(\rho)))=-i\mathrm{Tr}_z([H^{\mathrm{int}},\mathcal{K}_1(\rho)])\notag\\
L000241		&=-\frac{Q^{\dag}Q\rho}{i\delta+\kappa_z/2}+\frac{Q\rho Q^{\dag}}{-i\delta+\kappa_z/2}+\frac{Q\rho Q^{\dag}}{i\delta+\kappa_z/2}-\frac{\rho Q^{\dag}Q}{-i\delta+\kappa_z/2}\notag\\
L000242		&=2\alpha\big(Q\rho Q^{\dag}-\frac{1}{2}\{Q^{\dag}Q,\rho\}\big)+i[\delta H,\rho],
L000243	\end{align}
L000244	where $\alpha=\kappa_z(2\delta^2+\kappa_z^2/2)^{-1}$, $\delta H=\beta Q^{\dag}Q$, and $\beta=\delta[\delta^2+(\kappa_z/2)^2]^{-1}$.
L000245	
L000246	Combining the zeroth-, first-, and second-order contributions in the adiabatic–elimination expansion, we obtain the effective master equation governing the reduced slow subsystem,
L000247	\begin{align}
L000248		\dot{\rho}=-i[H-\delta H,\rho]+\Gamma_{\mathrm{eff}}\mathcal{L}[Q]\rho,
L000249	\end{align}
L000250	with $\Gamma_\mathrm{eff}=2\alpha$.
L000251	
L000252	When the auxiliary mode is resonant with the system, one has $\beta=0$, and therefore $\delta H=0$. In this case, the effective dissipative rate reduces to $\Gamma_{\mathrm{eff}}=4/\kappa_z$. Moreover, the operator $Q$ can be written as $Q=g(p_aa+p_bb)$. As long as both coupling coefficients $g_a$ and $g_b$ are nonzero, they can be rescaled so that $|p_a||p_b|=1$, with the overall magnitude absorbed into the coupling constant $g$. Consequently, the dissipative rate used in the main text is $\Gamma=g\sqrt{\Gamma_{\mathrm{eff}}}$, and the effective Lindblad operator is $L_c=\sqrt{\Gamma}(p_aa+p_bb)$.
L000253	
L000254	\subsection{Constructing $L_c$ via a common waveguide}
L000255	We demonstrate that directly coupling two cavity modes to a common 1D waveguide also provides a route to construct the collective dissipation operator $L_c$. Considering two cavity modes $a$ and $b$ at positions $R_a=-d/2$ and $R_b=d/2$, the annihilation operators for the left- and right-propagating modes in the waveguide are denoted by $z_{k,L}$ and $z_{k,R}$. The total Hamiltonian is
L000256	\begin{align}
L000257		H^{\rm tot}=H+H^z+H^{\rm int},
L000258	\end{align}
L000259	where the waveguide Hamiltonian is
L000260	\begin{align}
L000261		H^z=\sum_k \nu_k(z_{k,L}^{\dag}z_{k,L}+ z_{k,R}^{\dag}z_{k,R}),
L000262	\end{align}
L000263	with $k$ denotes the wave vector of the propagating mode and $\nu_k$ is the corresponding mode frequency. The interaction Hamiltonian is
L000264	\begin{align}
L000265		H^{\rm int}=\sum_{h=a,b}\sum_k\frac{g_k^h}{\sqrt{2}}(h^{\dag}z_{k,R}e^{-i\nu_kt}+hz_{k,R}^{\dag}e^{i\nu_kt}+h^{\dag}z_{k,L}e^{i\nu_kt}+hz_{k,L}^{\dag}e^{-i\nu_kt}).
L000266	\end{align}
L000267	
L000268	The evolution of the operator $O$ (cavity modes subspace) in the Heisenberg picture is given by
L000269	\begin{align}
L000270		\frac{dO}{dt}=i[H,O]+i\sum_{h=a,b}\sqrt{\frac{\Gamma_h}{2}}([h^{\dag},O]z_{r_h,R}+[h,O]z_{r_h,R}^{\dag}+[h^{\dag},O]z_{r_h,L}+[h,O]z_{r_h,L}^{\dag}).
L000271	\end{align}
L000272	In deriving the dissipative terms, we have used
L000273	\begin{align}
L000274		\sum_k|g_k|^2\int e^{-i(\omega-\nu_k)(t-\tau)}d\tau&=\sum_k2\pi|g_k|^2 \delta(\omega-\nu_k)=L/2\pi\int dk2\pi|g_k|^2\delta(\omega-\nu_k)\notag\\
L000275		&=L/2\pi\int dk2\pi|g_k|^2\delta(\omega-\nu_k)=|g_0|^2/v_g,
L000276	\end{align}
L000277	which yields the decay rate
L000278	$\Gamma_h = |g_0^h|^2 / v_g$ under the standard normalization $g_k^h = g_0^h/\sqrt{L}$.
L000279	Here, $v_g = d\nu_k/dk$ denotes the group velocity of the transmission mode. Under the short-delay (Markovian) approximation, where retardation effects are neglected, the free-evolution approximation $h(t-\tau)\approx h(t)e^{i\omega_h\tau}
L000280	=h(t)e^{ik_hd}$, where $\tau=d/v_g$ is the propagation delay associated with the cavity separation $d$, and $k_h=\omega_h/v_g$. Together with the slowly-varying decay-rate approximation $\Gamma_h(t-\tau)\approx \Gamma_h(t)$, and the assumption of vacuum input fields for the waveguide. The above formula can be further expressed as~\cite{PhysRevA.102.053720}
L000281	\begin{align}
L000282		\frac{dO}{dt}=i[H,O]+\sum_{h=a,b}\frac{\Gamma_h}{2}([h^{\dag},O]h-[h,O]h^{\dag})+\sum_{h\neq h'=a,b}\frac{\sqrt{\Gamma_a\Gamma_b}}{2}([h^{\dag},O]h'e^{ik_{h'}d}-h'^{\dag}[h,O]e^{-ik_{h'}d}).
L000283	\end{align}
L000284	
L000285	Accordingly, the expectation value of $O$ can be obtained. Since the above relation holds for an arbitrary operator $O$, the corresponding equation of motion for the density matrix can be directly identified, yielding the master equation
L000286	\begin{align}
L000287		\frac{d\rho}{dt}=-i[H+H_J,\rho]+\sum_{h,h'=a,b}\Gamma_{hh'}\mathcal{D}(h,h')\rho,
L000288	\end{align}
L000289	where the waveguide-mediated exchange interaction between the two cavities is $H_J=J'a^{\dag}b+J'^*b^{\dag}a$, with $J'=-i\sqrt{\Gamma_a\Gamma_b}/4(e^{ik_bd}-e^{-ik_ad})$. Here, $\Gamma_{hh}=\Gamma_h$ denotes the individual decay rate, and $\Gamma_{ab}=\Gamma_{ba}^*=\sqrt{\Gamma_a\Gamma_b}(e^{ik_bd}+e^{-ik_ad})/2$ characterizes the cooperative dissipation. The superoperator is defined as $\mathcal{D}(A, B)\rho=B\rho A^{\dag}-1/2\{A^{\dag}B,\rho\}$. When the separation between the two cavities satisfies $d=2n\pi/k$, with $n\in\mathbb{Z}$, the coherent interaction vanishes, $H_J=0$, while the collective dissipative coupling $L_c=\sqrt{\Gamma}(p_aa+p_bb)$ is constructed,
L000290	\begin{align}
L000291		\frac{d\rho}{dt}=-i[H,\rho]+\mathcal{L}[L_c]\rho,
L000292	\end{align}
L000293	where we have set $k_a=k_b=k$, $\Gamma_a=\Gamma_b$.
L000294	
L000295	\section{Evolution of the operators in the squeezing framework}
L000296	In this section, we consider a general scenario where the cavity modes $a$ and $b$ are squeezed with parameters $(r_a, \theta_a)$ and $(r_b, \theta_b)$, respectively, and both are coupled to a common squeezed reservoir characterized by $(r_c, \theta_c)$.
L000297	
L000298	We first present the derivation of the master equation describing two cavity modes collectively coupled to a squeezing reservoir, using the waveguide as a concrete example. Other interactions are omitted for clarity and discussed later. The interaction Hamiltonian of the cavity modes with the reservoir is
L000299	\begin{align}
L000300		H_{\rm int}=\sum_k\big[\frac{g_k^a}{\sqrt{2}}(a^{\dag}z_{k,R}e^{i(\omega_a-\nu_k)t}+a^{\dag}z_{k,L}e^{i(\omega_a+\nu_k)t})+\frac{g_k^b}{\sqrt{2}}(b^{\dag}z_{k,R}e^{i(\omega_b-\nu_k)t}+b^{\dag}z_{k,L}e^{i(\omega_b+\nu_k)t})\big]+\rm{H.c.},
L000301	\end{align}
L000302	within the Born–Markov approximation, the dynamics of the system is governed by
L000303	\begin{align}
L000304		\dot{\rho}(t)=-i\mathrm{Tr}_z[H_\mathrm{int}(t),\rho(0)\otimes\rho_z(0)]-\int_0^td\tau\mathrm{Tr}_z[H_\mathrm{int}(t),[H_\mathrm{int}(\tau),\rho(\tau)\otimes\rho_z(0)]],\label{eqh}
L000305	\end{align}
L000306	where $\rho_z(0)$ denotes the initial state of the reservoir.
L000307	
L000308	For the squeezed vacuum reservoir, the density operator is given by
L000309	\begin{align}
L000310		\rho_z=|\xi\rangle\langle\xi|=\prod_kS_k(\xi)|0_k\rangle\langle0_k|S_k^{\dag}(\xi),
L000311	\end{align}
L000312	where the squeeze operator is
L000313	\begin{align}
L000314		S_k(\xi)=\exp\big(\frac{1}{2}\xi^*z_{k_0+k}z_{k_0-k}-\frac{1}{2}\xi z_{k_0+k}^{\dag}z_{k_0-k}^{\dag}\big),
L000315	\end{align}
L000316	with $\xi=r_c\exp(i\theta_c)$. The correlations can then be obtained:
L000317	\begin{align}
L000318		\langle z_k\rangle&=\prod_q\langle0_q|S_q^{\dag}z_kS_q|0_q\rangle=0,\notag\\
L000319		\langle z_k^{\dag}\rangle&=\prod_q\langle0_q|S_q^{\dag}z_k^{\dag}S_q|0_q\rangle=0,\notag\\
L000320		\langle z_k^{\dag}z_{k'}\rangle&=\prod_q\langle0_q|S_q^{\dag}z_k^{\dag}S_qS_q^{\dag}z_{k'}S_q|0_q\rangle=N\delta_{kk'},\notag\\
L000321		\langle z_kz_{k'}^{\dag}\rangle&=\prod_q\langle0_q|S_q^{\dag}z_kS_qS_q^{\dag}z_{k'}^{\dag}S_q|0_q\rangle=(N+1)\delta_{kk'},\notag\\
L000322		\langle z_kz_{k'}\rangle&=\prod_q\langle0_q|S_q^{\dag}z_kS_qS_q^{\dag}z_{k'}S_q|0_q\rangle=-M^*\delta_{k',2k_0-k},\notag\\
L000323		\langle z_k^{\dag}z_{k'}^{\dag}\rangle&=\prod_q\langle0_q|S_q^{\dag}z_k^{\dag}S_qS_q^{\dag}z_{k'}^{\dag}S_q|0_q\rangle=-M\delta_{k',2k_0-k},
L000324	\end{align}
L000325	where $N=\sinh^2r_c$, $M=e^{-i\theta_c}\sinh r_c\cosh r_c$, and $k_0=\omega_0/v_g$, with $\omega_0$ is the central frequency of the squeezing device. These correlations are satisfied for both the left- and right-propagating modes.
L000326	
L000327	Substituting $H_{\rm int}$ into Eq.~(\ref{eqh}) and using the aforementioned correlation relationship, we derive the master equation in the squeezed framework
L000328	\begin{align}
L000329		\dot{\rho}=&\Gamma_aN(a^{\dag}\rho a-1/2\{a a^{\dag},\rho\})+\Gamma_a(N+1)(a\rho a^{\dag}-1/2\{a^{\dag}a,\rho\})-\Gamma_aM(a\rho a-1/2\{a a,\rho\})\notag\\
L000330		&-\Gamma_aM^*(a^{\dag}\rho a^{\dag}-1/2\{a^{\dag}a^{\dag},\rho\})+\Gamma_bN(b^{\dag}\rho b-1/2\{b b^{\dag},\rho\})+\Gamma_b(N+1)(b\rho b^{\dag}-1/2\{b^{\dag}b,\rho\})\notag\\
L000331		&-\Gamma_bM(b\rho b-1/2\{b b,\rho\})-\Gamma_bM^*(b^{\dag}\rho b^{\dag}-1/2\{b^{\dag}b^{\dag},\rho\})+\Gamma_{ab}N(a^{\dag}\rho b-1/2\{b a^{\dag},\rho\}+b^{\dag}\rho a\notag\\
L000332		&-1/2\{a b^{\dag},\rho\})+\Gamma_{ab}(N+1)(a\rho b^{\dag}-1/2\{b^{\dag} a,\rho\}+b\rho a^{\dag}-1/2\{a^{\dag} b,\rho\})-\Gamma_{ab}M(a\rho b-1/2\{b a,\rho\}\notag\\
L000333		&+b\rho a-1/2\{ab,\rho\})-\Gamma_{ab}M^*(a^{\dag}\rho b^{\dag}-1/2\{b^{\dag} a^{\dag},\rho\}+b^{\dag}\rho a^{\dag}-1/2\{a^{\dag}b^{\dag},\rho\}),
L000334	\end{align}
L000335	with dissipation rate $\Gamma_h=|g_0^h|^2/v_g$, $\Gamma_{ab}=\sqrt{\Gamma_a\Gamma_b}$. Assuming $\Gamma_a=\Gamma_b$, this expression can be written as
L000336	\begin{align}
L000337		\dot{\rho}= (N+1)\mathcal{L}[L_c]\rho+N\mathcal{L}[L_c^{\dag}]\rho-M\mathcal{L}'[L_c]\rho-M^*\mathcal{L}'[L_c^{\dag}]\rho.
L000338	\end{align}
L000339	
L000340	Furthermore, the Hamiltonian of the system in the squeezing framework is $$H_s=S_b^{\dag}S_a^{\dag}(H+H_{\rm NL}^a+H_{\rm NL}^b)S_aS_b=\omega_s(a_s^{\dag}a_s+b_s^{\dag}b_s)+[Je^{i\varphi}(\cosh{r_a}a_s^{\dag}-e^{i\theta_a}\sinh{r_a}a_s)(\cosh{r_b}b_s-e^{-i\theta_b}\sinh{r_b}b^{\dag}_s)+\mathrm{H.c.}],$$ including the local dissipation of the cavity modes, the full master equation can be written as
