L000516	\section{Scattering coefficient matrix of the optical isolator}
L000517	When both cavity modes are squeezed, the corresponding quantum Langevin equations~(QLEs) can be found in Eq.~(6) in the main text. To analyze the transmission properties, we linearize the QLEs as $dV/dt=-MV+D V_{\mathrm{in}}$, where $V=(a_s,b_s,a_s^{\dag},b_s^{\dag})^T$ is the vector of system operators, $V_{\mathrm{in}}=(a^{\mathrm{in}}, b^{\mathrm{in}}, a^{\mathrm{in}\dag}, b^{\mathrm{in}\dag})^T$, and $D=\mathrm{diag}(\sqrt{\kappa_a}, \sqrt{\kappa_b}, \sqrt{\kappa_a}, \sqrt{\kappa_b})$. The coefficient matrix $M$ can be written as
L000518	\begin{align}
L000519		M=\begin{pmatrix}
L000520			-\frac{\Lambda_a+i\omega_s}{2}&0&0&0\\
L000521			2J(e^{i\Delta\theta}\sinh r_a\sinh r_b-\cosh r_a\cosh r_b)&-\frac{\Lambda_b+i\omega_s}{2}&2J(e^{-i\theta_a}\sinh r_a\cosh r_b-e^{-i\theta_b}\cosh r_a\sinh r_b)&0\\
L000522			0&0&-\frac{\Lambda_a-i\omega_s}{2}&0\\
L000523			2J(e^{i\theta_a}\sinh r_a\cosh r_b-e^{i\theta_b}\cosh r_a\sinh r_b)&0&2J(e^{-i\Delta\theta}\sinh r_a\sinh r_b-\cosh r_a\cosh r_b)&\frac{i\omega_s-\Lambda_b}{2}
L000524		\end{pmatrix}.\notag
L000525	\end{align}
L000526	Transforming to the frequency domain yields
L000527	\begin{align}
L000528		\overline{V}(\omega)=(M-i\omega \mathbb{I})^{-1}D \overline{V}_{\mathrm{in}}(\omega).
L000529	\end{align}
L000530	Using the input-output relation $\nu_{\mathrm{out}}+\nu_{\mathrm{in}}=\sqrt{\gamma_{\nu}}\nu$~\cite{PhysRevA.31.3761}, the output field is $\overline{V}_{\mathrm{out}}(\omega)=U(\omega)\overline{V}_{\mathrm{in}}(\omega)$, where
L000531	\begin{align}
L000532		\overline{V}_{\mathrm{out}}=\big(a^{\mathrm{out}}(\omega), b^{\mathrm{out}}(\omega), a^{\mathrm{out}\dag}(\omega), b^{\mathrm{out}\dag}(\omega)\big)^T,
L000533	\end{align}
L000534	and
L000535	\begin{align}
L000536		U(\omega)=D(M-i\omega \mathbb{I})^{-1}D-\mathbb{I},
L000537	\end{align}
L000538	which can be expressed as
L000539	\begin{align}
L000540		\begin{pmatrix}
L000541			-\frac{2\kappa_a}{\Lambda_a+i(2\omega+\omega_s)}&0&0&0\\
L000542			\frac{8J\sqrt{\kappa_a\kappa_b}(\cosh r_a\cosh r_b-e^{i\Delta\theta}\sinh r_a\sinh r_b)}{[\Lambda_a+i(2\omega+\omega_s)][\Lambda_b+i(2\omega+\omega_s)]}&\frac{-2\kappa_b}{\Lambda_b+i(2\omega+\omega_s)}&\frac{8J\sqrt{\kappa_a\kappa_b}(e^{-i\theta_b}\cosh r_a\sinh r_b-e^{-i\theta_a}\sinh r_a\cosh r_b)}{(i\Lambda_a-2\omega+\omega_s)(-i\Lambda_b+2\omega+\omega_s)}&0\\
L000543			0&0&-\frac{2\kappa_a}{\Lambda_a+i(2\omega-\omega_s)}&0\\
L000544			\frac{8J\sqrt{\kappa_a\kappa_b}(e^{i\theta_b}\cosh r_a\sinh r_b-e^{i\theta_a}\sinh r_a\cosh r_b)}{(i\Lambda_b-2\omega+\omega_s)(-i\Lambda_a+2\omega+\omega_s)}&0&\frac{8J\sqrt{\kappa_a\kappa_b}(\cosh r_a\cosh r_b-e^{-i\Delta\theta}\sinh r_a\sinh r_b)}{[\Lambda_a+i(2\omega-\omega_s)][\Lambda_b+i(2\omega-\omega_s)]}&\frac{-2\kappa_b}{\Lambda_b+i(2\omega-\omega_s)}
L000545		\end{pmatrix}-\mathbb{I}.\label{eq26}
L000546	\end{align}
L000547	
L000548	Substituting
L000549	\begin{align}
L000550		a_s^{\mathrm{out}}(\omega)=U_{11}(\omega)a_s^{\mathrm{in}}(\omega)+U_{12}(\omega)b^{\mathrm{in}}(\omega)+U_{13}(\omega)a_s^{\mathrm{in}\dag}(\omega)+U_{14}(\omega)b^{\mathrm{in}\dag}(\omega),\notag\\
L000551		b^{\mathrm{out}}(\omega)=U_{21}(\omega)a_s^{\mathrm{in}}(\omega)+U_{22}(\omega)b^{\mathrm{in}}(\omega)+U_{23}(\omega)a_s^{\mathrm{in}\dag}(\omega)+U_{24}(\omega)b^{\mathrm{in}\dag}(\omega),
L000552	\end{align}
L000553	and their Hermitian conjugate into the definition of the output field spectrum, $s_{\nu}^{\mathrm{out}}(\omega)=\int d\omega'\langle\overline{\nu}^{\mathrm{out}\dag}(\omega')\overline{\nu}^{\mathrm{out}}(\omega)\rangle$~\cite{PhysRevA.85.021801}, we can obtain
L000554	\begin{align}
L000555		s_{a}^{\mathrm{out}}(\omega)=\int d \omega'\sum_{j,k=1}^4U_{1j}^*(\omega')U_{1k}(\omega)\langle\overline{V}_{\mathrm{in},j}^{\dag}(\omega')\overline{V}_{\mathrm{in},k}(\omega)\rangle,\notag\\
L000556		s_{b}^{\mathrm{out}}(\omega)=\int d \omega'\sum_{j,k=1}^4U_{2j}^*(\omega')U_{2k}(\omega)\langle\overline{V}_{\mathrm{in},j}^{\dag}(\omega')\overline{V}_{\mathrm{in},k}(\omega)\rangle.
L000557	\end{align}
L000558	The subscript of $U(\omega)$ indicates its matrix element. Utilizing the correlation of the input field $\langle \nu^{\mathrm{in}\dag}(\omega')\nu^{\mathrm{in}}(\omega)\rangle=s_{\nu}^{\mathrm{in}}(\omega)\delta(\omega-\omega')$, we can obtain
L000559	\begin{align}
L000560		s_{a}^{\mathrm{out}}(\omega)=\big(|U_{11}|^2+|U_{13}|^2\big)s_{a}^{\mathrm{in}}(\omega)+\big(|U_{12}|^2+|U_{14}|^2\big)s_{b}^{\mathrm{in}}(\omega)+|U_{13}|^2+|U_{14}|^2,\notag\\
L000561		s_{b}^{\mathrm{out}}(\omega)=\big(|U_{21}|^2+|U_{23}|^2\big)s_{a}^{\mathrm{in}}(\omega)+\big(|U_{22}|^2+|U_{24}|^2\big)s_{b}^{\mathrm{in}}(\omega)+|U_{23}|^2+|U_{24}|^2.\end{align}
L000562	
L000563	Furthermore, the spectrum of the output field can be expressed as \begin{align}
L000564		S_{\mathrm{out}}(\omega)=T(\omega)S_{\mathrm{in}}(\omega)+S_{\mathrm{vac}}(\omega),
L000565	\end{align}
L000566	with $S_{\mathrm{in}}(\omega)=\big(s_{a}^{\mathrm{in}}(\omega), s_{b}^{\mathrm{in}}(\omega)\big)^T$, $S_{\mathrm{out}}(\omega)=\big(s_{a}^{\mathrm{out}}(\omega), s_{b}^{\mathrm{out}}(\omega)\big)^T$, $S_{\mathrm{vac}}(\omega)=\big(s_{a}^{\mathrm{vac}}(\omega), s_{b}^{\mathrm{vac}}(\omega)\big)^T$, and
L000567	\begin{align}
L000568		T(\omega)=
L000569		\begin{pmatrix}
L000570			|U_{11}|^2+|U_{13}|^2&|U_{12}|^2+|U_{14}|^2\\
L000571			|U_{21}|^2+|U_{23}|^2&|U_{22}|^2+|U_{24}|^2
L000572		\end{pmatrix},
L000573	\end{align}
L000574	$s_{\nu}^{\mathrm{vac}}$ is the output spectrum contributing from the
L000575	input vacuum field, which is given by $s_{a}^{\mathrm{vac}}=|U_{13}|^2+|U_{14}|^2$ and $s_{b}^{\mathrm{vac}}=|U_{23}|^2+|U_{24}|^2$. With Eq.~(\ref{eq26}), the transmission coefficient of the signal from mode $b$ to mode $a$ vanishes, $T_{ab}=0$, whereas the transmission coefficient from mode $a$ to mode $b$ is
L000576	\begin{align}
L000577		T_{ba}
L000578		=&\frac{64J^2\kappa_a\kappa_b}{\Lambda_b^2+(2\omega+\omega_s)^2}
L000579		\left[
L000580		\frac{
L000581			2+\cosh\!\bigl[2(r_a-r_b)\bigr]
L000582			+\cosh\!\bigl[2(r_a+r_b)\bigr]
L000583			-2\cos\Delta\theta\sinh2r_a\sinh2r_b
L000584		}{
L000585			4\bigl[\Lambda_a^2+(2\omega+\omega_s)^2\bigr]
L000586		}
L000587		\right. \notag\\
L000588		&\left.
L000589		+\frac{
L000590			\sinh^2 r_a \cosh^2 r_b + \cosh^2 r_a \sinh^2 r_b
L000591			-\tfrac{1}{2}\cos\Delta\theta\sinh2r_a\sinh2r_b
L000592		}{
L000593			\Lambda_a^2+(-2\omega+\omega_s)^2
L000594		}
L000595		\right].
L000596	\end{align}
